/**
 * OUpgradePage — 升级提示 / Premium Wall
 * 用户触达免费限额时显示。
 */
'use client';

import type { ReactNode } from 'react';

export interface OUpgradePageProps {
  /** 触发场景描述,如"已用完本月 100 次查询" */
  reason?: string;
  /** 推荐升级套餐名 */
  planName?: string;
  /** 核心卖点(3-4条) */
  highlights?: string[];
  onUpgrade?: () => void;
  onDismiss?: () => void;
  /** 嵌入模式(在页面内弹出)vs 全页 */
  variant?: 'page' | 'modal';
  topSlot?: ReactNode;
  lang?: 'zh' | 'en';
}

export function OUpgradePage({
  reason,
  planName = 'Pro',
  highlights,
  onUpgrade,
  onDismiss,
  variant = 'page',
  topSlot,
  lang = 'zh',
}: OUpgradePageProps) {
  const isEn = lang === 'en';

  const defaultHighlights = isEn
    ? ['Unlimited usage', 'Priority support', 'Advanced features', 'Team collaboration']
    : ['无限次使用', '优先客户支持', '高级功能解锁', '团队协作'];

  const items = highlights ?? defaultHighlights;

  const inner = (
    <div className="oui-upgrade-content">
      {topSlot}

      <div style={{ fontSize: '2.5rem', marginBottom: 'var(--space-4)' }}>⚡</div>

      <h2 className="oui-upgrade-title">
        {isEn ? `Upgrade to ${planName}` : `升级到 ${planName}`}
      </h2>

      {reason && (
        <p className="oui-upgrade-reason">{reason}</p>
      )}

      <ul className="oui-upgrade-highlights">
        {items.map((h, i) => (
          <li key={i} className="oui-upgrade-highlight">
            <span style={{ color: 'var(--primary)' }}>✓</span>
            <span>{h}</span>
          </li>
        ))}
      </ul>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)', alignItems: 'center', width: '100%' }}>
        <button type="button" className="oui-btn-primary oui-w-full" style={{ maxWidth: '280px' }}
          onClick={onUpgrade}>
          {isEn ? `Upgrade to ${planName}` : `立即升级 ${planName}`}
        </button>
        {onDismiss && (
          <button type="button" onClick={onDismiss}
            style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 'var(--text-xs)', color: 'var(--muted-foreground)', padding: 'var(--space-1)' }}>
            {isEn ? 'Maybe later' : '稍后再说'}
          </button>
        )}
      </div>
    </div>
  );

  if (variant === 'modal') {
    return (
      <div className="oui-upgrade-modal-backdrop" role="dialog" aria-modal="true">
        <div className="oui-upgrade-modal">{inner}</div>
      </div>
    );
  }

  return <div className="oui-upgrade-page">{inner}</div>;
}
