/**
 * OVerifyEmailPage — 邮箱验证落地页
 * 注册后发验证邮件,用户点链接进来。
 * URL: /verify-email?token=xxx
 */
'use client';

import { useEffect, useState } from 'react';
import { OAuthShell } from '../shell/OAuthShell';

export interface OVerifyEmailPageProps {
  token?: string;
  /** mount 后自动验证 */
  onVerify?: (token: string) => Promise<{ success: boolean; error?: string }>;
  /** 验证成功后的动作(跳转等) */
  onSuccess?: () => void;
  onResend?: () => void | Promise<void>;
  lang?: 'zh' | 'en';
}

export function OVerifyEmailPage({
  token,
  onVerify,
  onSuccess,
  onResend,
  lang = 'zh',
}: OVerifyEmailPageProps) {
  const isEn = lang === 'en';
  const [status, setStatus] = useState<'pending' | 'success' | 'error' | 'idle'>(
    token ? 'pending' : 'idle'
  );
  const [error, setError]   = useState('');
  const [resent, setResent] = useState(false);

  useEffect(() => {
    if (!token || !onVerify) { setStatus('idle'); return; }
    setStatus('pending');
    onVerify(token).then(res => {
      if (res.success) {
        setStatus('success');
        setTimeout(() => onSuccess?.(), 1500);
      } else {
        setStatus('error');
        setError(res.error ?? (isEn ? 'Verification failed.' : '验证失败，请重试。'));
      }
    });
  }, [token]);

  const resend = async () => {
    await onResend?.();
    setResent(true);
  };

  const content = {
    pending: { icon: '⏳', title: isEn ? 'Verifying…' : '验证中…',      sub: '' },
    success: { icon: '✓',  title: isEn ? 'Email verified!' : '邮箱验证成功！', sub: isEn ? 'Redirecting…' : '即将跳转…' },
    error:   { icon: '⚠',  title: isEn ? 'Verification failed' : '验证失败', sub: error },
    idle:    { icon: '📧', title: isEn ? 'Check your email' : '请查收邮件',  sub: isEn ? 'Click the link in the email to verify your account.' : '点击邮件中的链接完成邮箱验证。' },
  }[status];

  return (
    <OAuthShell title={content.title}>
      <div style={{ textAlign: 'center', display: 'flex', flexDirection: 'column', gap: 'var(--space-4)', alignItems: 'center' }}>
        <div style={{ fontSize: '3rem', lineHeight: 1 }}>{content.icon}</div>
        {content.sub && (
          <p style={{ fontSize: 'var(--text-sm)', color: 'var(--muted-foreground)' }}>{content.sub}</p>
        )}
        {(status === 'error' || status === 'idle') && onResend && (
          <button type="button" onClick={resend} disabled={resent}
            className="oui-btn-primary" style={{ minWidth: '180px' }}>
            {resent
              ? (isEn ? 'Sent!' : '已发送！')
              : (isEn ? 'Resend verification email' : '重新发送验证邮件')}
          </button>
        )}
      </div>
    </OAuthShell>
  );
}
