/**
 * OCookieBanner — GDPR Cookie 授权横幅
 *
 * 欧盟用户访问时必须弹出,获得明确同意后才能设置非必要 cookie。
 *
 * 用法:
 *   const [consent, setConsent] = useLocalStorage('cookie-consent', null);
 *   {!consent && (
 *     <OCookieBanner
 *       onAcceptAll={() => setConsent('all')}
 *       onAcceptNecessary={() => setConsent('necessary')}
 *       privacyPolicyUrl="/privacy"
 *     />
 *   )}
 */
'use client';

import { useState } from 'react';

export interface OCookieBannerProps {
  onAcceptAll: () => void;
  onAcceptNecessary: () => void;
  onCustomize?: () => void;
  privacyPolicyUrl?: string;
  lang?: 'zh' | 'en';
  /** 横幅位置,默认底部 */
  position?: 'bottom' | 'top';
}

export function OCookieBanner({
  onAcceptAll,
  onAcceptNecessary,
  onCustomize,
  privacyPolicyUrl = '/privacy',
  lang = 'zh',
  position = 'bottom',
}: OCookieBannerProps) {
  const [visible, setVisible] = useState(true);
  if (!visible) return null;

  const accept = (type: 'all' | 'necessary') => {
    setVisible(false);
    if (type === 'all') onAcceptAll();
    else onAcceptNecessary();
  };

  const isEn = lang === 'en';

  return (
    <div
      className="oui-cookie-banner"
      data-position={position}
      role="dialog"
      aria-label={isEn ? 'Cookie consent' : 'Cookie 授权'}
      aria-live="polite"
    >
      <div className="oui-cookie-banner__content">
        <p className="oui-cookie-banner__text">
          {isEn
            ? <>We use cookies to improve your experience. See our <a href={privacyPolicyUrl} className="oui-cookie-banner__link">Privacy Policy</a>.</>
            : <>我们使用 Cookie 提升使用体验。详见<a href={privacyPolicyUrl} className="oui-cookie-banner__link">隐私政策</a>。</>
          }
        </p>
        <div className="oui-cookie-banner__actions">
          <button
            type="button"
            className="oui-cookie-banner__btn oui-cookie-banner__btn--secondary"
            onClick={() => accept('necessary')}
          >
            {isEn ? 'Necessary only' : '仅必要'}
          </button>
          {onCustomize && (
            <button
              type="button"
              className="oui-cookie-banner__btn oui-cookie-banner__btn--secondary"
              onClick={onCustomize}
            >
              {isEn ? 'Customize' : '自定义'}
            </button>
          )}
          <button
            type="button"
            className="oui-cookie-banner__btn oui-cookie-banner__btn--primary"
            onClick={() => accept('all')}
          >
            {isEn ? 'Accept all' : '接受全部'}
          </button>
        </div>
      </div>
    </div>
  );
}
