/**
 * OPricingPage — 定价页框架
 *
 * 用法:
 *   <OPricingPage
 *     title="选择适合你的方案"
 *     plans={[
 *       {
 *         id: 'free',
 *         name: '免费版',
 *         description: '个人使用,永久免费',
 *         price: { monthly: 0, yearly: 0, currency: '¥' },
 *         features: [
 *           { text: '每月 100 次查询', included: true },
 *           { text: '优先支持', included: false },
 *         ],
 *         cta: '免费开始',
 *       },
 *       {
 *         id: 'pro',
 *         name: 'Pro',
 *         featured: true,
 *         badge: '最受欢迎',
 *         price: { monthly: 99, yearly: 79, currency: '¥' },
 *         features: [...],
 *         cta: '立即升级',
 *         onSelect: (billing) => router.push(`/checkout?plan=pro&billing=${billing}`),
 *       },
 *       {
 *         id: 'enterprise',
 *         name: '企业版',
 *         price: 'custom',
 *         features: [...],
 *         cta: '联系我们',
 *       },
 *     ]}
 *   />
 */
'use client';

import { useState, type ReactNode } from 'react';

export type BillingCycle = 'monthly' | 'yearly';

export interface PlanFeature {
  text: string;
  included: boolean;
}

export interface PlanPrice {
  monthly: number;
  yearly: number;
  currency: string;       // '¥' | '$' | '€'
  yearlyLabel?: string;   // 默认 '/月 按年计费'
}

export interface OPricingPlan {
  id: string;
  name: string;
  description?: string;
  /** 'custom' = 联系销售,不显示价格 */
  price: PlanPrice | 'custom';
  features: PlanFeature[];
  cta: string;
  featured?: boolean;
  badge?: string;
  /** 点击 CTA 时触发 */
  onSelect?: (billing: BillingCycle) => void;
  /** 自定义 CTA 节点(优先级高于 onSelect) */
  ctaNode?: ReactNode;
}

export interface OPricingPageProps {
  title?: string;
  subtitle?: string;
  plans: OPricingPlan[];
  /** 是否显示月/年切换,默认 true */
  showBillingToggle?: boolean;
  /** 年付折扣提示文案 */
  yearlyBadge?: string;
  /** 页面顶部插槽 */
  headerSlot?: ReactNode;
  /** 价格卡片下方插槽(FAQ / 对比表等) */
  footerSlot?: ReactNode;
}

export function OPricingPage({
  title = '选择你的方案',
  subtitle,
  plans,
  showBillingToggle = true,
  yearlyBadge = '省 20%',
  headerSlot,
  footerSlot,
}: OPricingPageProps) {
  const [billing, setBilling] = useState<BillingCycle>('monthly');

  return (
    <div className="oui-pricing-page">

      {/* Header */}
      <div className="oui-pricing-header">
        {headerSlot}
        <h1 className="oui-pricing-title">{title}</h1>
        {subtitle && <p className="oui-pricing-subtitle">{subtitle}</p>}

        {/* 月/年切换 */}
        {showBillingToggle && (
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 'var(--space-6, 24px)' }}>
            <div className="oui-billing-toggle">
              <button
                type="button"
                className="oui-billing-toggle__btn"
                aria-pressed={billing === 'monthly'}
                onClick={() => setBilling('monthly')}
              >
                按月付
              </button>
              <button
                type="button"
                className="oui-billing-toggle__btn"
                aria-pressed={billing === 'yearly'}
                onClick={() => setBilling('yearly')}
              >
                按年付
                {yearlyBadge && (
                  <span style={{
                    marginLeft: '6px', fontSize: 'var(--text-xs)', fontWeight: 700,
                    background: 'var(--primary)', color: 'var(--primary-foreground)',
                    padding: '1px 6px', borderRadius: '99px',
                  }}>
                    {yearlyBadge}
                  </span>
                )}
              </button>
            </div>
          </div>
        )}
      </div>

      {/* 价格卡片 */}
      <div className="oui-pricing-grid">
        {plans.map(plan => {
          const price = plan.price;
          const amount = price === 'custom'
            ? null
            : billing === 'yearly' ? price.yearly : price.monthly;
          const currency = price !== 'custom' ? price.currency : '';
          const period = price !== 'custom'
            ? (billing === 'yearly' ? (price.yearlyLabel ?? '/月 · 按年计费') : '/月')
            : '';

          return (
            <div key={plan.id} className="oui-plan-card" data-featured={plan.featured ? 'true' : undefined}>
              {plan.badge && <div className="oui-plan-badge">{plan.badge}</div>}

              <div>
                <div className="oui-plan-name">{plan.name}</div>
                {plan.description && (
                  <div className="oui-plan-desc" style={{ marginTop: 'var(--space-1)' }}>
                    {plan.description}
                  </div>
                )}
              </div>

              <div className="oui-plan-price">
                {price === 'custom' ? (
                  <span className="oui-plan-price__custom">联系我们</span>
                ) : (
                  <>
                    <span className="oui-plan-price__currency">{currency}</span>
                    <span className="oui-plan-price__amount">{amount}</span>
                    <span className="oui-plan-price__period">{period}</span>
                  </>
                )}
              </div>

              <ul className="oui-plan-features">
                {plan.features.map((f, i) => (
                  <li key={i} className={`oui-plan-feature${f.included ? '' : ' oui-plan-feature--muted'}`}>
                    <span className="oui-plan-feature__icon" aria-hidden>
                      {f.included ? '✓' : '–'}
                    </span>
                    {f.text}
                  </li>
                ))}
              </ul>

              {plan.ctaNode ?? (
                <button
                  type="button"
                  className={plan.featured ? 'oui-btn-primary oui-w-full' : 'oui-btn-secondary oui-w-full'}
                  style={plan.featured
                    ? {}
                    : { padding: 'var(--space-2-5, 10px)', fontSize: 'var(--text-sm)', fontWeight: 600, borderRadius: 'var(--radius)', cursor: 'pointer' }
                  }
                  onClick={() => plan.onSelect?.(billing)}
                >
                  {plan.cta}
                </button>
              )}
            </div>
          );
        })}
      </div>

      {footerSlot && (
        <div style={{ marginTop: 'var(--space-12, 48px)' }}>{footerSlot}</div>
      )}
    </div>
  );
}

export type { BillingCycle as OBillingCycle };
